class DevStudioCompletionTests(unittest.TestCase):
    def test_source_names_regex_uses_python_314_compatible_flags(self):
        source = (
            "class StoryCommand:\n"
            "    selected_step = 'START'\n"
            "    def run(self):\n"
            "        self.current_step = selected_step\n"
        )
        names = {item["label"] for item in CompletionEngine._source_candidates(source)}
        self.assertTrue(
            {"StoryCommand", "selected_step", "run", "current_step"}.issubset(names))


class _StepDebugSample:
    def __init__(self):
        self.ready = True
        self.values = []

    def sample_step(self):
        self.values.append("first")
        if self.ready:
            self.values.append("conditional")
        return "NEXT_STEP"

    def return_only_condition(self):
        if self.ready:
            return "READY"
        return "WAIT"


class StepDebugNextStateTests(unittest.TestCase):
    def test_mapping_fallback_selects_state_after_current(self):
        states = ["STEP_1", "STEP_2", "STEP_3", "STEP_4"]
        self.assertEqual(
            recommended_next_state("STEP_3", [], states), "STEP_4")

    def test_explicit_backtrack_is_kept_when_forward_is_not_returnable(self):
        states = ["STEP_1", "STEP_2", "STEP_3", "STEP_4"]
        self.assertEqual(
            recommended_next_state("STEP_3", ["STEP_2", "STEP_3"], states),
            "STEP_2")

    def test_declared_forward_return_wins_over_earlier_candidate(self):
        states = ["STEP_1", "STEP_2", "STEP_3", "STEP_4"]
        self.assertEqual(
            recommended_next_state(
                "STEP_3", ["STEP_2", "STEP_4", "STEP_3"], states),
            "STEP_4")


class _StartOverrideSample:
    def __init__(self):
        self.STATE_MAIN_FUNCTION = {"MAIN_1_Z_LANK": self.main_story}
        self.main_current_state = "MAIN_STATE_INIT"
        self.main_current_state_init = ""
        self.STATE_1_STORY_FUNCTION = {
            "1_STORY_A": self.story_a,
            "1_STORY_B": self.story_b,
        }
        self._1_story_current_state = "1_STORY_A"
        self._1_story_current_state_init = ""

    def main_story(self):
        self._1_story_current_state = self.STATE_1_STORY_FUNCTION[
            self._1_story_current_state]()
        return "MAIN_1_Z_LANK"

    def story_a(self):
        return "1_STORY_B"

    def story_b(self):
        return "1_STORY_B"


class CommandStartOverrideTests(unittest.TestCase):
    def test_nested_story_start_uses_existing_init_attributes(self):
        command = _StartOverrideSample()
        applied = apply_command_start_override(
            command, "STATE_1_STORY_FUNCTION", "1_STORY_B")
        self.assertEqual(command._1_story_current_state_init, "1_STORY_B")
        self.assertEqual(command.main_current_state_init, "MAIN_1_Z_LANK")
        self.assertEqual(
            [(item["attribute"], item["value"]) for item in applied],
            [("_1_story_current_state_init", "1_STORY_B"),
             ("main_current_state_init", "MAIN_1_Z_LANK")],
        )

    def test_explicit_parent_route_wins_for_shared_generated_state(self):
        command = _StartOverrideSample()
        command.COMMAND_RUN_STATE_PARENTS = {
            "STATE_1_STORY_FUNCTION": (
                "STATE_MAIN_FUNCTION", "MAIN_1_Z_LANK"),
        }

        applied = apply_command_start_override(
            command, "STATE_1_STORY_FUNCTION", "1_STORY_B")

        self.assertEqual(command._1_story_current_state_init, "1_STORY_B")
        self.assertEqual(command.main_current_state_init, "MAIN_1_Z_LANK")
        self.assertEqual(len(applied), 2)


class CommandRunOptionsTests(unittest.TestCase):
    def test_filtering_end_chapter_does_not_reset_selected_start(self):
        selected_start = "2_STORY_TOWER_79"
        visible_end_candidates = ["7_STORY_START_CHECK", "7_STORY_END"]
        self.assertEqual(
            preserve_location_selection(
                selected_start, visible_end_candidates),
            selected_start)
        self.assertEqual(
            preserve_location_selection("", visible_end_candidates),
            "7_STORY_START_CHECK")
        self.assertEqual(
            preserve_location_selection(
                "（終了場所を指定しない）", visible_end_candidates,
                "（終了場所を指定しない）"),
            "（終了場所を指定しない）")

    def test_za_tower_step_is_exposed_for_both_run_location_pickers(self):
        path = os.path.abspath(os.path.join(
            os.path.dirname(__file__), "..", "SerialController", "Commands",
            "PythonCommands", "ZA", "ZA_story", "ZA_story.py"))
        with open(path, "r", encoding="utf-8-sig") as stream:
            result = discover_command_run_options(
                stream.read(), class_name="ZA_story")
        item = next(row for row in result["locations"]
                    if row.get("value") == "2_STORY_TOWER_79")
        self.assertTrue(result["enabled"])
        self.assertEqual(item["label"], "2_STORY_TOWER_79")
        self.assertEqual(item["variable"], "STATE_2_STORY_FUNCTION")

    def test_runtime_state_fallback_keeps_za_start_selector_available(self):
        source_path = os.path.join(SERIAL_CONTROLLER, "Window.py")
        with tokenize.open(source_path) as stream:
            source = stream.read()
        module = ast.parse(source)
        method = next(
            item for node in module.body if isinstance(node, ast.ClassDef)
            for item in node.body if isinstance(item, ast.FunctionDef)
            and item.name == "_runtime_command_run_options")
        method.decorator_list = []
        function_module = ast.Module(body=[method], type_ignores=[])
        ast.fix_missing_locations(function_module)
        namespace = {
            "discover_runtime_debug_options":
                discover_runtime_debug_options,
        }
        exec(compile(function_module, source_path, "exec"), namespace)

        command = types.SimpleNamespace(
            COMMAND_RUN_SETTINGS=True,
            COMMAND_DEBUG_OPTIONS=(
                {"attribute": "ResetDebug",
                 "label": "ResetDebug（リセット復帰確認）",
                 "description": "初回だけリセット復帰を検証します。",
                 "default": False},
                {"attribute": "fastread", "label": "fastread",
                 "default": True},
                {"attribute": "TESTADDCODE", "label": "TESTADDCODE",
                 "default": False},
                {"attribute": "testcode", "label": "testcode",
                 "default": False},
            ),
            COMMAND_STEP_LABELS={"START": "最初から"},
            COMMAND_STEP_DESCRIPTIONS={"START": "開始地点"},
            STATE_MAIN_FUNCTION={"START": object(), "END": object()},
            STATE_1_STORY_FUNCTION={"STEP_A": object()},
            unrelated={"IGNORED": object()},
            ResetDebug=False,
            fastread=True,
            TESTADDCODE=0,
            testcode=0,
        )
        result = namespace["_runtime_command_run_options"](command)
        self.assertTrue(result["enabled"])
        self.assertTrue(result["runtime_fallback"])
        self.assertEqual(
            [(item["variable"], item["value"])
             for item in result["locations"]],
            [("STATE_MAIN_FUNCTION", "START"),
             ("STATE_MAIN_FUNCTION", "END"),
             ("STATE_1_STORY_FUNCTION", "STEP_A")])
        self.assertEqual(result["locations"][0]["description"], "開始地点")
        self.assertEqual(result["locations"][0]["label"], "最初から")
        self.assertEqual(
            [item["attribute"] for item in result["debug_options"]],
            ["ResetDebug", "fastread", "TESTADDCODE", "testcode"])
        self.assertEqual(
            result["debug_options"][0]["label"],
            "ResetDebug（リセット復帰確認）")
        self.assertEqual(
            result["debug_options"][0]["description"],
            "初回だけリセット復帰を検証します。")

        generated = types.SimpleNamespace(
            COMMAND_RUN_SETTINGS=True,
            COMMAND_STEP_LABELS={"READY": "開始準備"},
            COMMAND_STEP_DESCRIPTIONS={"READY": "準備画面から開始"},
            STEP_LABELS=["準備", "実行"],
            STEP_KEYS=["READY", "RUN"],
        )
        generated_result = namespace["_runtime_command_run_options"](
            generated)
        self.assertEqual(
            [(item["label"], item["description"])
             for item in generated_result["locations"]],
            [("開始準備", "準備画面から開始"), ("実行", "")])

    def test_required_start_selector_uses_runtime_fallback_instead_of_skipping(self):
        source_path = os.path.join(SERIAL_CONTROLLER, "Window.py")
        with tokenize.open(source_path) as stream:
            source = stream.read()
        module = ast.parse(source)
        method = next(
            item for node in module.body if isinstance(node, ast.ClassDef)
            for item in node.body if isinstance(item, ast.FunctionDef)
            and item.name == "_prompt_command_run_settings")
        calls = [
            node.func.attr for node in ast.walk(method)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
        ]
        self.assertIn("_runtime_command_run_options", calls)
        self.assertIn("_prompt_command_source_error_action", calls)
        self.assertIn("_bring_command_console_to_front", calls)
        self.assertIn("showerror", calls)

        plain_calls = [
            node.func.id for node in ast.walk(method)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
        ]
        self.assertIn("print", plain_calls)

    def test_source_error_popup_can_copy_the_complete_error(self):
        source_path = os.path.join(SERIAL_CONTROLLER, "Window.py")
        with tokenize.open(source_path) as stream:
            source = stream.read()
        module = ast.parse(source)
        method = next(
            item for node in module.body if isinstance(node, ast.ClassDef)
            for item in node.body if isinstance(item, ast.FunctionDef)
            and item.name == "_prompt_command_source_error_action")
        calls = [
            node.func.attr for node in ast.walk(method)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
        ]
        self.assertIn("clipboard_clear", calls)
        self.assertIn("clipboard_append", calls)
        self.assertIn("エラーをコピー", source)

    def test_start_option_source_error_is_returned_for_analysis_output(self):
        source_path = os.path.join(SERIAL_CONTROLLER, "Window.py")
        with tokenize.open(source_path) as stream:
            source = stream.read()
        module = ast.parse(source)
        method = next(
            item for node in module.body if isinstance(node, ast.ClassDef)
            for item in node.body if isinstance(item, ast.FunctionDef)
            and item.name == "_command_run_options")
        function_module = ast.Module(body=[method], type_ignores=[])
        ast.fix_missing_locations(function_module)
        namespace = {
            "inspect": inspect,
            "os": os,
            "discover_command_run_options": discover_command_run_options,
        }
        exec(compile(function_module, source_path, "exec"), namespace)

        class BrokenCommand:
            pass

        class Dummy:
            def _command_classes(self, _command_name):
                return [BrokenCommand]

        with tempfile.NamedTemporaryFile(
                mode="w", suffix=".py", encoding="utf-8", delete=False) as stream:
            stream.write("class BrokenCommand:\n    broken(:\n")
            broken_path = stream.name
        try:
            with mock.patch.object(
                    inspect, "getsourcefile", return_value=broken_path):
                result = namespace["_command_run_options"](
                    Dummy(), "Broken")
        finally:
            os.unlink(broken_path)
        self.assertFalse(result["enabled"])
        self.assertEqual(len(result["source_errors"]), 1)
        self.assertIn("invalid syntax", result["source_errors"][0])

