class InputSetRuntimeRegistryTests(unittest.TestCase):
    def test_current_process_has_reusable_identity(self):
        self.assertEqual(process_identity(os.getpid()), process_identity(os.getpid()))

    def test_multiple_instances_are_listed_and_one_can_unregister(self):
        with tempfile.TemporaryDirectory() as temporary:
            path = os.path.join(temporary, "active_input_sets.json")
            identities = {101: "101:start-a", 202: "202:start-b"}
            provider = lambda pid: identities.get(pid)
            first = ActiveInputSetRegistry(
                path, profile="default", identity_provider=provider,
                token="first", pid=101)
            second = ActiveInputSetRegistry(
                path, profile="default", identity_provider=provider,
                token="second", pid=202)
            first.set_active("Switch_No1", "PokeCon Switch 1")
            second.set_active("Switch_No2", "PokeCon Switch 2")

            entries = read_active_input_sets(path, identity_provider=provider)
            self.assertEqual(
                [(entry["input_set"], entry["pid"]) for entry in entries],
                [("Switch_No1", 101), ("Switch_No2", 202)])

            first.close()
            entries = read_active_input_sets(path, identity_provider=provider)
            self.assertEqual([entry["input_set"] for entry in entries], ["Switch_No2"])

    def test_crashed_or_pid_reused_entry_is_pruned(self):
        with tempfile.TemporaryDirectory() as temporary:
            path = os.path.join(temporary, "active_input_sets.json")
            identities = {303: "303:first-start"}
            provider = lambda pid: identities.get(pid)
            registry = ActiveInputSetRegistry(
                path, identity_provider=provider, token="stale", pid=303)
            registry.set_active("Switch_No3")

            identities[303] = "303:reused-pid"
            self.assertEqual(
                read_active_input_sets(path, identity_provider=provider), [])
            with open(path, "r", encoding="utf-8") as stream:
                self.assertEqual(json.load(stream)["entries"], {})

    def test_current_instance_can_be_excluded_from_popup_results(self):
        with tempfile.TemporaryDirectory() as temporary:
            path = os.path.join(temporary, "active_input_sets.json")
            provider = lambda pid: "{}:start".format(pid)
            registry = ActiveInputSetRegistry(
                path, identity_provider=provider, token="self", pid=404)
            registry.set_active("Switch_No4")
            self.assertEqual(registry.entries(include_self=False), [])
            self.assertEqual(
                registry.entries(include_self=True)[0]["input_set"], "Switch_No4")

    def test_last_focused_live_pokecon_wins_even_after_browser_focus(self):
        with tempfile.TemporaryDirectory() as temporary:
            path = os.path.join(temporary, "active_windows.json")
            provider = lambda pid: "{}:start".format(pid)
            first = ActiveInputSetRegistry(
                path, identity_provider=provider, token="first", pid=501)
            second = ActiveInputSetRegistry(
                path, identity_provider=provider, token="second", pid=502)
            first.mark_focused(marker=100)
            second.mark_focused(marker=200)
            self.assertFalse(first.is_last_focused())
            self.assertTrue(second.is_last_focused())
            # No focus event is written when the user moves to a browser, so
            # the last PokeCon remains the full-rate preview owner.
            self.assertTrue(second.is_last_focused())
            first.mark_focused(marker=300)
            self.assertTrue(first.is_last_focused())
            second.close()
            first.close()

    def test_manual_input_follows_foreground_pokecon_then_survives_browser(self):
        entries = [
            {"pid": 501, "token": "first", "started_at": "2026-08-16T10:00:00",
             "last_focused_ns": 100},
            {"pid": 502, "token": "second", "started_at": "2026-08-16T10:01:00",
             "last_focused_ns": 200},
        ]
        # Clicking a PokeCon switches immediately even before its asynchronous
        # focus marker reaches the shared registry.
        self.assertEqual(last_active_pokecon_pid(entries, foreground_pid=501), 501)
        # Chrome is not a registered PokeCon, so the last selected PokeCon is
        # retained as the keyboard/gamepad input target.
        self.assertEqual(last_active_pokecon_pid(entries, foreground_pid=999), 502)
        self.assertEqual(last_active_pokecon_pid(entries, foreground_pid=None), 502)

    def test_manual_input_owner_uses_newest_only_before_any_focus_marker(self):
        entries = [
            {"pid": 601, "started_at": "2026-08-16T10:00:00"},
            {"pid": 602, "started_at": "2026-08-16T10:01:00"},
        ]
        self.assertEqual(last_active_pokecon_pid(entries, foreground_pid=999), 602)
        self.assertIsNone(last_active_pokecon_pid([], foreground_pid=602))

    def test_activity_registry_is_shared_outside_individual_profiles(self):
        path = default_window_activity_registry_path()
        self.assertEqual(os.path.basename(path), "active_windows.json")
        self.assertIn("PokeConModifiedExtension", path)

    def test_device_usage_is_shared_and_current_instance_is_excluded(self):
        with tempfile.TemporaryDirectory() as temporary:
            path = os.path.join(temporary, "active_windows.json")
            provider = lambda pid: "{}:start".format(pid)
            first = ActiveInputSetRegistry(
                path, profile="one", identity_provider=provider,
                token="first", pid=601)
            second = ActiveInputSetRegistry(
                path, profile="two", identity_provider=provider,
                token="second", pid=602)
            camera_key = canonical_device_key("camera", "USB Capture A")
            first.mark_focused(marker=100)
            first.set_device("camera", camera_key, "USB Capture A")
            second.mark_focused(marker=200)
            conflicts = device_usage_conflicts(
                second.entries(include_self=False), "camera", camera_key)
            self.assertEqual([item["pid"] for item in conflicts], [601])
            self.assertEqual(conflicts[0]["devices"]["camera"]["label"],
                             "USB Capture A")
            self.assertTrue(second.is_last_focused())
            first.set_active("Profile B", "Combined B")
            conflicts = device_usage_conflicts(
                second.entries(include_self=False), "camera", camera_key)
            self.assertEqual([item["pid"] for item in conflicts], [601])
            self.assertEqual(conflicts[0]["input_set"], "Profile B")
            self.assertEqual(conflicts[0]["devices"]["camera"]["label"],
                             "USB Capture A")
            first.set_active("")
            conflicts = device_usage_conflicts(
                second.entries(include_self=False), "camera", camera_key)
            self.assertEqual([item["pid"] for item in conflicts], [601])
            self.assertEqual(conflicts[0]["input_set"], "")
            first.set_device("camera", "", "")
            self.assertEqual(device_usage_conflicts(
                second.entries(include_self=False), "camera", camera_key), [])

    def test_confirmation_audio_output_claim_is_machine_wide(self):
        with tempfile.TemporaryDirectory() as temporary:
            path = os.path.join(temporary, "active_windows.json")
            provider = lambda pid: "{}:start".format(pid)
            first = ActiveInputSetRegistry(
                path, identity_provider=provider, token="first", pid=611)
            second = ActiveInputSetRegistry(
                path, identity_provider=provider, token="second", pid=612)
            output_key = canonical_device_key(
                "audio_output", "confirmation")
            first.set_device(
                "audio_output", output_key,
                "PokeCon confirmation playback")
            conflicts = device_usage_conflicts(
                second.entries(include_self=False),
                "audio_output", output_key)
            self.assertEqual([entry["pid"] for entry in conflicts], [611])
            first.set_device("audio_output", "", "")
            self.assertEqual(device_usage_conflicts(
                second.entries(include_self=False),
                "audio_output", output_key), [])

    def test_main_resource_role_is_unique_across_processes(self):
        with tempfile.TemporaryDirectory() as temporary:
            path = os.path.join(temporary, "active_windows.json")
            provider = lambda pid: "{}:start".format(pid)
            first = ActiveInputSetRegistry(
                path, identity_provider=provider, token="first", pid=701)
            second = ActiveInputSetRegistry(
                path, identity_provider=provider, token="second", pid=702)
            self.assertTrue(first.set_resource_state(main_requested=True))
            self.assertFalse(second.set_resource_state(main_requested=True))
            conflicts = main_resource_conflicts(second.entries(include_self=False))
            self.assertEqual([item["pid"] for item in conflicts], [701])
            first.close()
            self.assertTrue(second.set_resource_state(main_requested=True))


class SwitchUpdatePromptTests(unittest.TestCase):
    @staticmethod
    def _prompt_frame(selection):
        frame = numpy.full((720, 1280, 3), 75, dtype=numpy.uint8)
        cv2.rectangle(frame, (250, 173), (1033, 549),
                      (245, 245, 245), thickness=-1)
        color = (200, 200, 40)
        if selection == START_WITHOUT_UPDATE:
            cv2.rectangle(frame, (253, 395), (1028, 466),
                          color, thickness=5)
        elif selection == UPDATE_SELECTED:
            cv2.rectangle(frame, (636, 467), (1033, 549),
                          color, thickness=5)
        return frame

    def test_detects_only_the_selected_safe_update_prompt_option(self):
        self.assertEqual(detect_switch_update_prompt_selection(
            self._prompt_frame(START_WITHOUT_UPDATE)), START_WITHOUT_UPDATE)
        self.assertEqual(detect_switch_update_prompt_selection(
            self._prompt_frame(UPDATE_SELECTED)), UPDATE_SELECTED)
        self.assertIsNone(detect_switch_update_prompt_selection(
            numpy.zeros((720, 1280, 3), dtype=numpy.uint8)))

    def test_update_selection_gets_at_most_ten_up_inputs_and_no_a(self):
        source_path = os.path.join(
            SERIAL_CONTROLLER, "Commands", "PythonCommands", "ZA",
            "ZA_story", "ZA_story.py")
        with tokenize.open(source_path) as stream:
            tree = ast.parse(stream.read())
        method = next(
            item for node in tree.body if isinstance(node, ast.ClassDef)
            for item in node.body if isinstance(item, ast.FunctionDef)
            and item.name == "_reset_handle_switch_update_prompt")
        function = copy.deepcopy(method)
        function.decorator_list = []
        function_module = ast.Module(body=[function], type_ignores=[])
        ast.fix_missing_locations(function_module)
        namespace = {
            "Button": types.SimpleNamespace(A="A"),
            "Hat": types.SimpleNamespace(TOP="TOP"),
            "START_WITHOUT_UPDATE": START_WITHOUT_UPDATE,
            "UPDATE_SELECTED": UPDATE_SELECTED,
            "time": time,
        }
        exec(compile(function_module, source_path, "exec"), namespace)

        pressed = []
        states = []
        command = types.SimpleNamespace(
            _reset_update_prompt_up_count=0,
            _reset_update_prompt_last_confirm=0.0,
            _reset_switch_update_prompt_selection=(
                lambda: UPDATE_SELECTED),
            press=lambda button, **_kwargs: pressed.append(button),
            wait=lambda _seconds: None,
        )
        handler = namespace["_reset_handle_switch_update_prompt"]
        for _ in range(12):
            self.assertTrue(handler(command, states.append))
        self.assertEqual(pressed, ["TOP"] * 10)
        self.assertNotIn("A", pressed)
        self.assertEqual(states[-1], "WAIT_START_WITHOUT_UPDATE")

        command._reset_switch_update_prompt_selection = (
            lambda: START_WITHOUT_UPDATE)
        self.assertTrue(handler(command, states.append))
        self.assertEqual(pressed[-1], "A")
        self.assertEqual(states[-1], "CONFIRM_START_WITHOUT_UPDATE")


class ZaMapping52RecoveryTests(unittest.TestCase):
    @staticmethod
    def _load_methods():
        source_path = os.path.join(
            SERIAL_CONTROLLER, "Commands", "PythonCommands", "ZA",
            "ZA_story", "ZA_story.py")
        with tokenize.open(source_path) as stream:
            tree = ast.parse(stream.read())
        method_names = {
            "_2_story_mapping_37",
            "_2_story_mapping_39",
            "_2_story_mapping_52",
            "_2_story_mapping_54",
        }
        methods = {
            item.name: copy.deepcopy(item)
            for node in tree.body if isinstance(node, ast.ClassDef)
            for item in node.body if isinstance(item, ast.FunctionDef)
            and item.name in method_names
        }
        module = ast.fix_missing_locations(ast.Module(
            body=[methods[name] for name in sorted(method_names)],
            type_ignores=[]))
        namespace = {
            "Button": types.SimpleNamespace(B="B"),
        }
        exec(compile(module, source_path, "exec"), namespace)
        return namespace

    @staticmethod
    def _command(namespace, goto_result="WAIT", mappic_result=True):
        class Command:
            _2_story_mapping_37 = namespace["_2_story_mapping_37"]
            _2_story_mapping_39 = namespace["_2_story_mapping_39"]
            _2_story_mapping_52 = namespace["_2_story_mapping_52"]
            _2_story_mapping_54 = namespace["_2_story_mapping_54"]

            def __init__(self):
                self.check_picture = 0
                self.goto_result = goto_result
                self.goto_calls = []
                self.jump_count = 0
                self._2_story_mapping_52_54_loop_count = 0
                self._2_story_mapping_52_recovery_active = False

            def ZA_Common_goto(self, *args, **kwargs):
                self.goto_calls.append((args, kwargs))
                return self.goto_result

            def ZA_Common_mappic_check(self, **_kwargs):
                return mappic_result

            def ZA_Common_goto_jump(self):
                self.jump_count += 1

            def image_check(self, _name):
                return False

            def pressRep(self, *_args, **_kwargs):
                pass

            def wait(self, _seconds):
                pass

        return Command()

    def test_mapping37_uses_position2_only_when_returning_from_mapping52(self):
        namespace = self._load_methods()
        recovery = self._command(namespace, goto_result="START")
        recovery._2_story_mapping_52_recovery_active = True

        self.assertEqual(
            recovery._2_story_mapping_37(),
            "2_STORY_MAPPING_38")
        self.assertEqual(recovery.goto_calls, [((3, 0, 2), {})])

        normal = self._command(namespace, goto_result="START")
        self.assertEqual(
            normal._2_story_mapping_37(),
            "2_STORY_MAPPING_38")
        self.assertEqual(normal.goto_calls, [((3, 0, 1), {})])

    def test_mapping52_self_retry_never_starts_mapping37_recovery(self):
        namespace = self._load_methods()
        command = self._command(namespace)

        results = [command._2_story_mapping_52() for _ in range(10)]

        self.assertEqual(results, ["2_STORY_MAPPING_52"] * 10)
        self.assertEqual(command._2_story_mapping_52_54_loop_count, 0)
        self.assertFalse(command._2_story_mapping_52_recovery_active)
        self.assertEqual(
            command.goto_calls,
            [((4, 0, 1), {})] * 10)

    def test_fifth_mapping54_return_schedules_recovery_from_mapping52(self):
        namespace = self._load_methods()
        command = self._command(
            namespace, goto_result="MOVEPOINT_PIC", mappic_result=False)

        results = [command._2_story_mapping_54() for _ in range(5)]

        self.assertEqual(results, ["2_STORY_MAPPING_52"] * 5)
        self.assertEqual(command._2_story_mapping_52_54_loop_count, 0)
        self.assertTrue(command._2_story_mapping_52_recovery_active)
        goto_count = len(command.goto_calls)
        self.assertEqual(
            command._2_story_mapping_52(),
            "2_STORY_MAPPING_37")
        self.assertEqual(len(command.goto_calls), goto_count)

    def test_mapping39_success_returns_to_mapping52_only_during_recovery(self):
        namespace = self._load_methods()
        recovery = self._command(namespace, goto_result="MOVEPOINT_PIC")
        recovery._2_story_mapping_52_recovery_active = True

        self.assertEqual(
            recovery._2_story_mapping_39(),
            "2_STORY_MAPPING_52")
        self.assertFalse(recovery._2_story_mapping_52_recovery_active)
        self.assertEqual(recovery.jump_count, 1)

        normal = self._command(namespace, goto_result="MOVEPOINT_PIC")
        self.assertEqual(
            normal._2_story_mapping_39(),
            "2_STORY_MAPPING_40")
        self.assertEqual(normal.jump_count, 1)

    def test_mapping54_success_clears_loop_state(self):
        namespace = self._load_methods()
        command = self._command(namespace, goto_result="MOVEPOINT_PIC")
        command._2_story_mapping_52_54_loop_count = 4

        self.assertEqual(
            command._2_story_mapping_54(),
            "2_STORY_MAPPING_55")
        self.assertEqual(command._2_story_mapping_52_54_loop_count, 0)
        self.assertFalse(command._2_story_mapping_52_recovery_active)


