        class RclickAnimationCommand(BattleCommand):
            def __init__(self):
                super().__init__()
                self.cplus_checks = 0

            def image_check(self, name):
                if name == "END":
                    self.end_checks += 1
                    return self.end_checks >= 2
                if name == "POKEMON_ZA_C+":
                    self.cplus_checks += 1
                    # RCLICK前だけ表示され、演出後は一時的に消える。
                    return self.cplus_checks == 1
                return False

